import pandas as pd
import requests
from datetime import datetime, timezone

BASE = 'https://api.stlouisfed.org/fred/series/observations'
API_KEY = CREDENTIALS.get('FRED_API_KEY', '')
now_epoch = int(datetime.now(timezone.utc).timestamp())

SERIES = [
    ('VIXCLS', 'vix', 'CBOE Volatility Index (VIX)'),
    ('BAMLH0A0HYM2', 'hy_spread', 'ICE BofA US High Yield Option-Adjusted Spread'),
    ('BAMLC0A0CM', 'ig_spread', 'ICE BofA US Corporate Index Option-Adjusted Spread'),
    ('STLFSI2', 'stress_index', 'St. Louis Fed Financial Stress Index'),
    ('DTWEXBGS', 'dollar_index', 'Trade Weighted U.S. Dollar Index (Broad Goods & Services)'),
]

rows = []
for i in range(len(SERIES)):
    series_id = SERIES[i][0]
    label = SERIES[i][1]
    description = SERIES[i][2]

    resp = requests.get(
        BASE,
        params={
            'series_id': series_id,
            'api_key': API_KEY,
            'file_type': 'json',
            'sort_order': 'desc',
            'limit': 5,
        },
        timeout=30,
    )
    resp.raise_for_status()
    obs = resp.json().get('observations', [])

    valid = []
    for o in obs:
        if o.get('value', '.') != '.':
            valid.append(o)

    if not valid:
        continue

    latest = float(valid[0]['value'])
    prev = float(valid[1]['value']) if len(valid) >= 2 else latest
    change = round(latest - prev, 4)
    change_pct = round(((latest - prev) / prev) * 100, 2) if prev != 0 else 0.0

    # Fear level classification
    if label == 'vix':
        if latest > 35:
            fear_level = 'EXTREME_FEAR'
        elif latest > 25:
            fear_level = 'HIGH_FEAR'
        elif latest > 18:
            fear_level = 'ELEVATED'
        elif latest > 12:
            fear_level = 'NORMAL'
        else:
            fear_level = 'COMPLACENCY'
    elif label == 'hy_spread':
        if latest > 600:
            fear_level = 'CRISIS'
        elif latest > 450:
            fear_level = 'HIGH_STRESS'
        elif latest > 350:
            fear_level = 'ELEVATED'
        else:
            fear_level = 'NORMAL'
    elif label == 'stress_index':
        if latest > 1.5:
            fear_level = 'HIGH_STRESS'
        elif latest > 0.5:
            fear_level = 'ELEVATED'
        elif latest > -0.5:
            fear_level = 'NORMAL'
        else:
            fear_level = 'CALM'
    else:
        fear_level = 'RISING' if change > 0 else 'FALLING'

    rows.append({
        'series_id': series_id,
        'metric': label,
        'description': description,
        'latest_value': latest,
        'latest_date': valid[0].get('date', ''),
        'prior_value': prev,
        'change': change,
        'change_pct': change_pct,
        'fear_level': fear_level,
        '_epoch': now_epoch,
    })

df = pd.DataFrame(rows)
GENERATE_RESULTS(df)
